  ('9082421346522', 'interlock-shirt-with-zip-closure', 'Light Weight Interlock Shirt', 'A lightweight, relaxed-fit shirt crafted from 100% cotton interlock fabric, featuring a sleek zip closure in solid black. The smooth texture and breathable construction make it ideal for layering or wearing on its own, offering a clean and casual look with effortless comfort. This is a lightweight interlock shirt, not a sweatshirt.', 'Color tones may appear slightly different in imagery due to lighting conditions and display variations.', 1600, null, array['/images/interlock-shirt-with-zip-closure-1.webp', '/images/interlock-shirt-with-zip-closure-2.webp', '/images/interlock-shirt-with-zip-closure-3.webp', '/images/interlock-shirt-with-zip-closure-4.webp']::text[], array['shirts', 'all-top', 'landing-page-collection']::text[], 'active', 5),
  ('9082462273754', 'interlock-shirt-with-zip-closure-navy', 'Interlock Shirt with Zip Closure', 'A light-to-moderate weight, relaxed-fit shirt crafted from interlock fabric, featuring a sleek zip closure in navy blue. The smooth texture and polyester blend enhance durability while maintaining breathability, making it ideal for layering or wearing on its own. This is a moderate interlock shirt, not a sweatshirt.', 'Color tones may appear slightly different in imagery due to lighting conditions and display variations.', 2300, null, array['/images/interlock-shirt-with-zip-closure-navy-1.webp', '/images/interlock-shirt-with-zip-closure-navy-2.webp', '/images/interlock-shirt-with-zip-closure-navy-3.webp']::text[], array['shirts', 'all-top', 'landing-page-collection']::text[], 'active', 6),
  ('9083175928026', 'yarn-dyed-stripe-tee', 'Yarn Dyed Stripe Tee', 'This lightweight navy blue and white striped shirt is crafted from yarn-dyed jersey knit, offering exceptional comfort and breathability in warm weather. Designed with a touch of Lycra, it ensures controlled stretch while maintaining its shape, providing a refined fit that moves with you. Perfect for casual layering or solo wear.', 'Color tones may appear slightly different in imagery due to lighting conditions and display variations.', 2000, null, array['/images/yarn-dyed-stripe-tee-1.webp', '/images/yarn-dyed-stripe-tee-2.webp', '/images/yarn-dyed-stripe-tee-3.webp']::text[], array['t-shirts', 'all-top', 'landing-page-collection']::text[], 'active', 7),
  ('9015819993306', 'microgrid-quarter-zipper', 'Textured Quarter Zipper', 'A full-sleeve sweatshirt crafted from waffle thermal fabric, featuring ribbed hems and a minimalistic zip hook for a clean finish. The textured knit provides warmth and breathability, making it perfect for winter wear while maintaining a relaxed fit, whether layered or worn on its own.', 'Color tones may appear slightly different in imagery due to lighting conditions and display variations.', 3800, null, array['/images/microgrid-quarter-zipper-1.webp', '/images/microgrid-quarter-zipper-2.webp', '/images/microgrid-quarter-zipper-3.webp', '/images/microgrid-quarter-zipper-4.webp']::text[], array['quarter-zipper', 'all-top']::text[], 'active', 8),
